// Renders the skill cards from data/skills.js (generated by tools/build.py) and wires the
// copy buttons, the mode switch, the theme toggle and site-config links. Plain script, no dependencies, works from file:// too.
(function () {
  "use strict";

  var site = (window.EGM && window.EGM.site) || {};
  var skills = (window.EGM && window.EGM.skills) || [];

  function text(el, value) {
    if (value) el.textContent = value;
  }

  // Fill text and link targets from site.json, so the repo URL is configured in one place.
  document.querySelectorAll("[data-site]").forEach(function (el) {
    text(el, site[el.getAttribute("data-site")]);
  });
  document.querySelectorAll("[data-site-href]").forEach(function (el) {
    var base = site[el.getAttribute("data-site-href")];
    if (!base) return;
    el.setAttribute("href", base + (el.getAttribute("data-site-suffix") || ""));
  });

  function el(tag, className, value) {
    var node = document.createElement(tag);
    if (className) node.className = className;
    if (value) node.textContent = value;
    return node;
  }

  function slug(value) {
    return value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  }

  var COPY_ICON = '<svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="12" height="12" rx="2"/><path d="M5 15H4a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1h10a1 1 0 0 1 1 1v1"/></g></svg>';
  var TICK_ICON = '<svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" d="M5 12.5l4.5 4.5L19 7.5"/></svg>';

  // Icons are fixed strings; the label is set as text.
  function setLabel(button, icon, label) {
    button.innerHTML = icon;
    button.appendChild(el("span", "", label));
  }

  function card(skill) {
    var article = el("article", "skill");

    var head = el("div", "skill-head");
    head.appendChild(el("span", "skill-icon", skill.icon)).setAttribute("aria-hidden", "true");
    var titles = el("div");
    titles.appendChild(el("h4", "", skill.title));
    titles.appendChild(el("code", "", skill.command));
    head.appendChild(titles);
    article.appendChild(head);

    var body = el("div", "skill-body");
    body.appendChild(el("p", "purpose", skill.purpose));

    var facts = el("dl", "facts");
    facts.appendChild(el("dt", "", "Use it when"));
    facts.appendChild(el("dd", "", skill.use_when));
    facts.appendChild(el("dt", "", "You get"));
    facts.appendChild(el("dd", "", skill.you_get));
    body.appendChild(facts);

    var example = el("div", "example");
    example.appendChild(el("code", "", skill.example));
    var copy = el("button", "btn small copy-btn");
    copy.type = "button";
    setLabel(copy, COPY_ICON, "Copy");
    copy.setAttribute("aria-label", "Copy example: " + skill.example);
    copy.addEventListener("click", function () { flash(copy, copyText(skill.example)); });
    example.appendChild(copy);
    body.appendChild(example);

    var details = el("details");
    details.appendChild(el("summary", "", "Full description"));
    details.appendChild(el("p", "full", skill.description));
    details.appendChild(el("p", "source", "Defined in " + skill.source));
    body.appendChild(details);
    article.appendChild(body);
    return article;
  }

  // Skill cards, grouped in the order the groups first appear in skills.json.
  var grid = document.getElementById("skill-grid");
  if (grid && skills.length) {
    grid.textContent = "";
    var groups = [];
    skills.forEach(function (skill) {
      if (groups.indexOf(skill.group) < 0) groups.push(skill.group);
    });
    groups.forEach(function (name) {
      var group = el("section", "skill-group " + slug(name));
      group.appendChild(el("h3", "", name));
      var blurb = (site.groups || {})[name];
      if (blurb) group.appendChild(el("p", "group-blurb", blurb));
      var cards = el("div", "skill-list");
      skills.filter(function (s) { return s.group === name; }).forEach(function (skill) {
        cards.appendChild(card(skill));
      });
      group.appendChild(cards);
      grid.appendChild(group);
    });
  }

  // Mode switch in "How it works": the CSS shows the lines for the chosen mode.
  var modes = document.getElementById("modes");
  if (modes) {
    modes.querySelectorAll("[data-set-mode]").forEach(function (button) {
      button.addEventListener("click", function () {
        modes.setAttribute("data-mode", button.getAttribute("data-set-mode"));
        modes.querySelectorAll("[data-set-mode]").forEach(function (b) {
          b.setAttribute("aria-pressed", String(b === button));
        });
      });
    });
  }

  // Copy buttons. The text comes from the page so the button always copies what is shown.
  function copyText(value) {
    if (navigator.clipboard && window.isSecureContext) {
      return navigator.clipboard.writeText(value);
    }
    var area = document.createElement("textarea");
    area.value = value;
    area.setAttribute("readonly", "");
    area.style.position = "absolute";
    area.style.left = "-9999px";
    document.body.appendChild(area);
    area.select();
    var ok = document.execCommand("copy");
    document.body.removeChild(area);
    return ok ? Promise.resolve() : Promise.reject(new Error("copy failed"));
  }

  function flash(button, done) {
    if (!button.dataset.label) button.dataset.label = button.textContent.trim();
    // Keep the original width so a shorter "Copied" label does not shrink the button.
    if (!button.style.minWidth) button.style.minWidth = button.getBoundingClientRect().width + "px";
    clearTimeout(button._reset);
    done.then(function () {
      setLabel(button, TICK_ICON, "Copied");
      button.classList.add("copied");
    }, function () {
      setLabel(button, COPY_ICON, "Select and copy");
    }).then(function () {
      button._reset = setTimeout(function () {
        setLabel(button, COPY_ICON, button.dataset.label);
        button.classList.remove("copied");
      }, 1600);
    });
  }

  document.querySelectorAll("[data-copy]").forEach(function (button) {
    button.classList.add("copy-btn");
    setLabel(button, COPY_ICON, button.textContent.trim());
    button.addEventListener("click", function () {
      var which = button.getAttribute("data-copy");
      flash(button, copyText(which === "local" ? site.local_install_command : site.install_command));
    });
  });

  // Theme toggle: follows the system until the person picks one, then remembers it.
  var toggle = document.getElementById("theme-toggle");
  var system = window.matchMedia ? window.matchMedia("(prefers-color-scheme: dark)") : null;
  function isDark() {
    var chosen = document.documentElement.getAttribute("data-theme");
    return chosen ? chosen === "dark" : !!(system && system.matches);
  }
  function syncToggle() {
    var dark = isDark();
    toggle.classList.toggle("is-dark", dark);
    toggle.setAttribute("aria-label", dark ? "Switch to light theme" : "Switch to dark theme");
    toggle.setAttribute("title", dark ? "Switch to light theme" : "Switch to dark theme");
  }
  if (toggle) {
    syncToggle();
    if (system && system.addEventListener) system.addEventListener("change", syncToggle);
    toggle.addEventListener("click", function () {
      var next = isDark() ? "light" : "dark";
      document.documentElement.setAttribute("data-theme", next);
      try { localStorage.setItem("egm-theme", next); } catch (e) {}
      syncToggle();
    });
  }
})();
